// Source-bound tissue organization; catalogue categories do not supply causal defaults.
const extent = "selected-primary-results-methods-and-figure-legends-supplement-unread";
const commonLimit = "Primary-source reconstruction only: no raw-data replay, laboratory reproduction, independent scientific review, universal arising law, minimum carrier count or causal weight is admitted.";
const sources = [], entities = [], claims = [], relations = [], studies = [], comparisons = [], readiness = [];
const sourceIndex = new Map(), studyIndex = new Map(), findingIndex = new Map();
function publication(id, title, authors, year, doi, pmcid, journal, volume, issue, pages, locators, limit, url = null) {
  const source = { id, kind: "research-publication", title, authors, year, doi,
    url: url ?? (pmcid ? `https://pmc.ncbi.nlm.nih.gov/articles/${pmcid}/` : `https://doi.org/${doi}`),
    path: null, sha256: null, review: { extent, locators, limit } };
  sources.push(source);
  sourceIndex.set(id, { source, journal, volume, issue, pages });
}
function citation(sourceId, locator, role = "supports") {
  return { sourceId, locator, role, note: "Read primary passage within the declared extent; preparation, endpoint, time and inference boundaries remain local to this publication." };
}
function node(id, name, kind, statement, claimIds, coordinates, obligations = [], status = "evidence-scoped") {
  const nodeId = `org:${id}`;
  entities.push({ id: nodeId, name, kind, description: statement, claimIds, status,
    sourceCoordinates: coordinates, openObligations: [...obligations, commonLimit], level: 5 });
  readiness.push({ nodeId, role: kind === "context" ? "experimental-context" : kind === "definition" ? "definition" : "scoped-phenomenon", denotes: statement, instanceAdmission: "none", claimIds });
  return nodeId;
}
function study(id, sourceId, system, preparation, observable, finding, limitations, indexes = null, studyType = "primary-experiment") {
  const meta = sourceIndex.get(sourceId);
  if (!meta) throw new Error(`Unknown publication ${sourceId}`);
  const locators = indexes ? indexes.map(i => meta.source.review.locators[i]) : meta.source.review.locators;
  const methodId = `M-org-${id}`;
  const limits = [meta.source.review.limit, ...limitations, commonLimit];
  claims.push({ id: methodId, kind: "method", statement: preparation, scope: system, status: "method-contract",
    citations: locators.map(locator => citation(sourceId, locator, "method")), checkIds: [], limitations: limits, contextIds: [id] });
  const contextNodeId = node(`${id}-context`, `${id}: acquisition context`, "context", preparation, [methodId], locators.map(locator => ({ sourceId, locator })), limits, "definition");
  if (studyType === "computational-analysis") readiness.find(row => row.nodeId === contextNodeId).role = "model-context";
  const record = { id, sourceId, studyType, doi: meta.source.doi, journal: meta.journal, volume: meta.volume, issue: meta.issue, pages: meta.pages,
    system, preparation, observable, finding, limitations: limits, readExtent: extent, reviewedLocators: locators,
    metadataCheckedAt: "2026-10-22", metadataUrl: `https://doi.org/${meta.source.doi}`,
    correctionCheck: "The inspected primary article record and available Crossref DOI metadata supplied no explicit correction notice. This bounded check does not establish that no correction exists; unread supplementary material and raw data remain outside this reconstruction." };
  studies.push(record); studyIndex.set(id, { record, methodId, locators, limits });
}
function observation(id, name, studyId, statement, extraLimits = [], status = "publication-supported") {
  const context = studyIndex.get(studyId), claimId = `C-org-${id}`;
  if (!context) throw new Error(`Unknown study ${studyId}`);
  claims.push({ id: claimId, kind: "review-finding", statement, scope: context.record.system, status,
    citations: context.locators.map(locator => citation(context.record.sourceId, locator)), checkIds: [], limitations: [...context.limits, ...extraLimits], contextIds: [studyId] });
  node(id, name, "scoped-process", statement, [claimId, context.methodId], context.locators.map(locator => ({ sourceId: context.record.sourceId, locator })), extraLimits);
  relations.push({ id: `organismal:${studyId}-measures-${id}`, source: `org:${studyId}-context`, target: `org:${id}`, kind: "descriptive",
    role: context.record.studyType === "computational-analysis" ? "computation-context" : "measurement-context",
    assertion: "The declared acquisition or analytical input defines the preparation and interpretation boundary of this finding.", claimIds: [context.methodId, claimId], contextIds: [studyId] });
  findingIndex.set(id, { claimId, studyId }); return claimId;
}
function operating(source, target, studyId, assertion, bearer, input, observable, limit) {
  const context = studyIndex.get(studyId), a = findingIndex.get(source), b = findingIndex.get(target);
  if (a.studyId !== studyId || b.studyId !== studyId) throw new Error("Functional endpoints must share their tested preparation");
  relations.push({ id: `organismal:${source}-supports-${target}`, source: `org:${source}`, target: `org:${target}`, kind: "functional-support", role: "scoped-operating-support", assertion,
    claimIds: [...new Set([a.claimId, b.claimId, context.methodId])], contextIds: [studyId],
    carrier: { contextIds: [studyId], citations: context.locators.map(locator => ({ sourceId: context.record.sourceId, locator })),
      interpretation: { bearer, input, observable, limit }, countingStatus: "unoperationalized", numericalAdmission: "none" } });
}

