function comparison(id, candidate, alternative, findingIds, discriminator, limit) {
  comparisons.push({ id, candidate, alternative,
    sourceIds: [...new Set(findingIds.map(findingId => studyIndex.get(findingIndex.get(findingId).studyId).record.sourceId))],
    discriminator, result: "conditional-support", limit,
    assumptions: ["Keep species, material, cell state, exposure history, acquisition and model boundaries distinct.", "Assays within one publication are not independent scientific replications.", commonLimit],
    claimIds: findingIds.map(findingId => findingIndex.get(findingId).claimId) });
}
comparison("organismal-niche-support-versus-necessity", "A helper-cell contribution can be substitutable and genotype/context dependent.", "Paneth cells are universally necessary for intestinal stem-cell renewal.", ["paneth-supported-organoid-output", "intestinal-wnt-pulse-output", "paneth-genetic-necessity-boundary", "paneth-independent-renewal"], "Sorted-cell co-culture/Wnt substitution supports one culture contribution, while independently published Atoh1 models retain renewal without Paneth cells.", "Different genetics and culture/in-vivo conditions prevent a clean numerical replication claim; Atoh1/Notch bypass and alternative Wnt remain unresolved.");
comparison("organismal-growth-versus-architecture", "Conditions supporting early expansion may fail later differentiation or coherent organization.", "More proliferation, Wnt or matrix degradability necessarily improves tissue formation.", ["intestinal-growth-pattern-dissociation", "isc-expansion-response", "isc-growth-organization-failure", "isc-staged-organoid-formation"], "Wnt add-back can rescue growth with cystic architecture; degradable stiff PEG increases colony formation while organization declines; dynamic support admits later buds.", "The comparisons are stage/material dependent and do not define one universal optimal sequence or sign.");
comparison("organismal-closure-versus-regeneration", "Closure, stage-specific rebuilding and regenerative restart are distinct outcomes.", "A closed viable wound has regenerated the missing tissue and a failed stump permanently lacks competence.", ["closed-scarred-stump", "regeneration-late-depletion-response", "regeneration-restart-boundary", "cardiac-lineage-regeneration"], "Early versus late axolotl depletion changes outcome severity; reamputation in a replenished context restarts growth; a separate zebrafish lineage assay identifies existing-cell contribution.", "Reamputation changes multiple conditions; cross-species tissue comparison does not identify one identical regenerative mechanism or prove full physiological recovery.");
comparison("organismal-mechanical-context-versus-scalar-instruction", "Matrix mechanics acts through preparation-specific response spaces and stages.", "One bulk stiffness or nuclear YAP state uniquely determines cellular identity.", ["msc-marker-history-response", "d1-fate-matrix-response", "yap-localization-insufficiency", "isc-staged-organoid-formation"], "Relaxation/adhesion/history alter outcome, D1 nuclear YAP overlaps across fate biases, and expansion versus differentiation require different environmental histories.", "Different cell species, gel chemistry, dimensionality and modulus definitions prohibit a direct universal numerical transfer.");
comparison("organismal-matrix-oncogene-cooperation", "Matrix-associated invasion is conditional on the tested oncogenic background.", "Stiff matrix alone is sufficient to cause tissue malignancy.", ["mammary-invasion-cooperation", "mammary-lox-context-response"], "The factorial culture comparison includes matrix-only and oncogene-only noninvasive controls; distinct mouse LOX treatment supplies a bounded in-vivo complement.", "Glycation/LOX have effects beyond pure stiffness, and no human incidence or all-fibrosis progression law is established.");
comparison("organismal-body-model-versus-body-completeness", "Localized patterning/mechanics can be reconstructed without establishing a complete organism.", "A patterned or elongated stem-cell aggregate establishes all-organ anatomical coherence or a unique universal construction law.", ["radial-fate-domains", "gastruloid-polarization", "axis-mechanical-gradient", "axis-jamming-model-boundary", "organoid-growth-boundary"], "Culture axes/fate domains, embryonic measured fields and source continuum predictions have different preparation and representation roles.", "These observations organize limited cases; they do not prove all-species ontological stages, irreducibility or complete tissue-to-organism causation.");

